pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        // 1. Restrict to admissible domain: amount > 0 so deposit is meaningful
        vm.assume(amount > 0);

        // 2. Deploy an adversarial helper that reverts on receiving ETH
        Reverter reverter = new Reverter();

        // Fund the reverter address with the deposit amount and deposit into the contract
        vm.deal(address(reverter), amount);
        vm.prank(address(reverter));
        (bool ok,) = address(c).call{value: amount}("");
        require(ok, "deposit failed");

        // The reverter is now the caller with a non-zero balance in c
        // Record pre-conditions: contract has exactly `amount` ETH
        assertEq(address(c).balance, amount, "pre: contract balance must be deposited amount");

        // 3. Call withdraw as the reverter; the call will fail and return false, but the mutant does not check it
        vm.prank(address(reverter));
        c.withdraw();

        // 4. The property: after withdraw completes, the contract's ETH balance must be 0
        //    The reference C satisfies this (require enforces successful transfer, then resets balance).
        //    The mutant fails to transfer on revert, but still resets balance mapping to 0,
        //    leaving ETH physically locked in the contract.
        assertTrue(address(c).balance == 0, "contract ETH balance must be zero after withdraw");
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
}

