pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint256 additionalAmount) public {
        vm.assume(amount > 0 && additionalAmount > 0);
        address caller = address(this);
        vm.deal(caller, amount + additionalAmount);

        // First deposit to have a balance
        vm.prank(caller);
        (bool ok,) = address(c).call{value: amount}("");
        require(ok, "first deposit failed");

        uint256 contractBalanceBefore = address(c).balance;
        uint256 callerBalance = c.balances(caller);
        require(callerBalance == amount, "balance mismatch");

        // Additional deposit to increase contract balance beyond caller's recorded balance
        vm.prank(caller);
        (bool ok2,) = address(c).call{value: additionalAmount}("");
        require(ok2, "second deposit failed");

        uint256 contractBalanceAfterDeposits = address(c).balance;
        require(contractBalanceAfterDeposits == amount + additionalAmount, "deposits mismatch");

        // Record total Ether sent by withdraw
        uint256 balanceBeforeWithdraw = address(c).balance;
        vm.prank(caller);
        try c.withdraw() returns (bool) { 
            // withdrawal succeeded
        } catch {
            // withdrawal failed, no Ether sent
            assertTrue(address(c).balance == balanceBeforeWithdraw, "balance unchanged if withdraw fails");
            return;
        }
        uint256 balanceAfterWithdraw = address(c).balance;
        uint256 etherSent = balanceBeforeWithdraw - balanceAfterWithdraw;

        // Invariant: etherSent + balanceAfterWithdraw == balanceBeforeWithdraw (always true)
        // The bug allows withdrawing more than the recorded balance, breaking conservation.
        // Correct behavior: etherSent == callerBalance (the amount recorded for caller) because balances are zeroed.
        // If the contract conserves total Ether, etherSent cannot exceed the sum of all recorded balances.
        // Since no other address has balances, etherSent must not exceed the total recorded balances (which is callerBalance + additionalAmount).
        // The bug leaves balance unchanged, so a second withdraw would drain extra Ether.
        // We check: etherSent <= c.balances(caller) after withdrawal? In correct version it's 0, etherSent == amount.
        // Actually, we can check: contract's Ether balance + sum of all recorded balances >= initial balance? But we only have one mapping.
        // We use the fact that after a successful withdraw, the caller's balance must be zero in correct version, allowing us to assert:
        // The contract's Ether balance after withdrawal must be >= additionalAmount (the amount not belonging to the caller before withdrawal).
        // In buggy version, caller's balance is not zeroed, so it can withdraw again later, but here we just check that the amount withdrawn
        // equals what was recorded for caller, which the fuzzer can break by setting additionalAmount = 0? No, additionalAmount > 0 enforced.
        // Better: In correct version, after withdraw, caller's balance is 0. So subsequent withdraw would send 0. Bug: balance remains amount, can withdraw again.
        // So we assert: c.balances(caller) == 0. This is the universal property of correct version after successful withdraw.
        assertTrue(c.balances(caller) == 0, "caller balance not zero after withdraw");
    }
}

