contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount) public {
        // Restrict to a wide admissible domain: deposit>0, withdraw<=deposit to avoid revert from insufficient balance
        vm.assume(depositAmount > 0 && depositAmount < 1e36);
        vm.assume(withdrawAmount > 0 && withdrawAmount <= depositAmount);

        // Use a fresh caller to avoid balance/sequence interference from other calls
        address caller = address(uint160(uint256(keccak256(abi.encode(depositAmount, withdrawAmount)))));
        vm.deal(caller, depositAmount);

        // Deposit via fallback
        vm.prank(caller);
        (bool depOk, ) = address(c).call{value: depositAmount}("");
        require(depOk, "deposit failed");

