        bool withdrawOk;
        try c.withdraw() returns (bool) { withdrawOk = true; } catch { withdrawOk = false; }

        if (withdrawOk) {
            // After a successful withdraw, the caller's recorded balance must be strictly less than before.
            // Reference C zeroes it; mutant leaves it unchanged, so this fails for the mutant.
