contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 reenterAmount) public {
        // Bound amounts to a reasonable range to avoid overflow during test; keep it wide
        depositAmount = bound(depositAmount, 1, 100 ether);
        reenterAmount = bound(reenterAmount, 1, 100 ether);

        // Deploy a reentrant attacker
        ReentrantAttacker attacker = new ReentrantAttacker(address(c), reenterAmount);

        // Fund attacker with enough for deposit + gas
        vm.deal(address(attacker), depositAmount + reenterAmount + 10 ether);

        // Attacker deposits `depositAmount` into c
        attacker.deposit{value: depositAmount}();

        // Record contract balance before withdraw
        uint256 balBefore = address(c).balance;
        uint256 sumBalancesBefore = c.balances(address(attacker));

        // Attacker triggers withdraw, which re-enters c
        attacker.attack();

        // After the dust settles, check invariant: contract balance must equal sum of known balances
        uint256 balAfter = address(c).balance;
        uint256 sumBalancesAfter = c.balances(address(attacker));

        // The reference satisfies this; the mutant leaks Ether via reentrancy
        assertTrue(balAfter == sumBalancesAfter);
    }
