        uint256 sumBalances = c.balances(address(attacker)) + c.balances(address(this));
        uint256 contractBalanceAfter = address(c).balance;

        // The invariant: sum of all balances must equal the contract's balance
        assertEq(sumBalances, contractBalanceAfter);
    }
